import time
import threading

def task_func(delay_time: float = 1.0, num_threads: int = 5):
    if num_threads <= 0:
        return []

    messages = [None] * num_threads

    def worker(i, delay):
        if delay > 0:
            time.sleep(delay)
        messages[i] = f'Delay in thread {i} completed'

    threads = []
    for i in range(num_threads):
        t = threading.Thread(target=worker, args=(i, delay_time))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return messages
